<?php
require_once __DIR__.'/../config/conexion.php';require_once __DIR__.'/../config/funciones.php';require_once __DIR__.'/../config/auth.php';require_once __DIR__.'/../config/esquema.php';
protegerPanelAdmin();asegurarEsquemaBoutique($conexion);$empresa=obtenerEmpresa($conexion);$admin=adminActual();
function irMarcas($m,$t='ok'){$_SESSION['admin_mensaje']=$m;$_SESSION['admin_tipo_mensaje']=$t;header('Location: marcas.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){try{$a=$_POST['accion']??'';$id=(int)($_POST['id_marca']??0);
 if($a==='guardar'){$n=trim($_POST['nombre_marca']??'');$d=trim($_POST['descripcion_marca']??'');if($n==='')throw new RuntimeException('Escribe el nombre de la marca.');$dup=$conexion->prepare('SELECT id_marca FROM marcas WHERE LOWER(nombre_marca)=LOWER(:n) AND id_marca<>:id LIMIT 1');$dup->execute(['n'=>$n,'id'=>$id]);if($dup->fetch())throw new RuntimeException('Ya existe una marca con ese nombre.');if($id){$q=$conexion->prepare('UPDATE marcas SET nombre_marca=:n,descripcion_marca=:d,estado_marca=1 WHERE id_marca=:id');$q->execute(['n'=>$n,'d'=>$d?:null,'id'=>$id]);}else{$q=$conexion->prepare('INSERT INTO marcas(nombre_marca,descripcion_marca,estado_marca) VALUES(:n,:d,1)');$q->execute(['n'=>$n,'d'=>$d?:null]);}irMarcas($id?'Marca actualizada.':'Marca creada.');}
 if($a==='eliminar'&&$id){$q=$conexion->prepare('SELECT COUNT(*) FROM productos WHERE id_marca=:id');$q->execute(['id'=>$id]);if((int)$q->fetchColumn()>0)throw new RuntimeException('No se puede eliminar porque tiene productos asociados. Reasigna esos productos primero.');$conexion->prepare('DELETE FROM marcas WHERE id_marca=:id')->execute(['id'=>$id]);irMarcas('Marca eliminada.');}
}catch(Throwable $e){irMarcas('No se pudo procesar: '.$e->getMessage(),'error');}}
$editar=null;if(isset($_GET['editar'])){$q=$conexion->prepare('SELECT * FROM marcas WHERE id_marca=:id');$q->execute(['id'=>(int)$_GET['editar']]);$editar=$q->fetch();}$marcas=$conexion->query('SELECT * FROM marcas ORDER BY nombre_marca')->fetchAll();$mensaje=$_SESSION['admin_mensaje']??'';$tipo=$_SESSION['admin_tipo_mensaje']??'ok';unset($_SESSION['admin_mensaje'],$_SESSION['admin_tipo_mensaje']);
?>
