iv></aside><main class="admin-main"><header class="admin-topbar"><div><span class="admin-kicker">Catálogo</span><h1>Marcas</h1><p>Crea y administra las marcas disponibles en la tienda.</p></div></header><?php if($mensaje):?><div class="admin-alert <?=$tipo==='error'?'error':'ok'?>"><?=htmlspecialchars($mensaje)?></div><?php endif;?><section class="admin-crud-grid compact-form-grid"><article class="admin-panel-card admin-form-card"><h2><?=$editar?'Editar marca':'Nueva marca'?></h2><form method="post" class="admin-form"><input type="hidden" name="accion" value="guardar"><input type="hidden" name="id_marca" value="<?=intval($editar['id_marca']??0)?>"><label>Nombre<input name="nombre_marca" required value="<?=htmlspecialchars($editar['nombre_marca']??'')?>"></label><label>Descripción<textarea name="descripcion_marca" rows="4"><?=htmlspecialchars($editar['descripcion_marca']??'')?></textarea></label><div class="admin-form-actions"><button class="admin-btn primary">Guardar</button><?php if($editar):?><a class="admin-btn ghost" href="marcas.php">Cancelar</a><?php endif;?></div></form></article><article class="admin-panel-card admin-table-card"><div class="admin-panel-header"><div><h2>Listado</h2><p><?=count($marcas)?> marca(s)</p></div></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Nombre</th><th>Descripción</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach($marcas as $m):?><tr><td><strong><?=htmlspecialchars($m['nombre_marca'])?></strong></td><td><?=htmlspecialchars($m['descripcion_marca']??'—')?></td><td><span class="admin-badge <?=($m['estado_marca']??1)?'ok':'muted'?>"><?=($m['estado_marca']??1)?'Activa':'Inactiva'?></span></td><td class="admin-actions-cell"><details class="admin-actions-menu table-actions-menu"><summary aria-label="Acciones" title="Acciones">•••</summary><div class="admin-actions-dropdown"><a href="?editar=<?=$m['id_marca']?>"><span aria-hidden="true">✎</span> Editar</a><form method="post" onsubmit="return confirm('¿Eliminar esta marca?')"><input type="hidden" name="accion" value="eliminar"><input type="hidden" name="id_marca" value="<?=$m['id_marca']?>"><button type="submit" class="danger-action"><span aria-hidden="true">🗑</span> Eliminar</button></form></div></details></td></tr><?php endforeach;?></tbody></table></div></article></section></main></div></body></html>
